      <button class="mx-auto bg-white rounded-3xl border border-[#e9ecef] p-3 shadow-sm hover:shadow-md transition-shadow w-52 h-52 md:w-60 md:h-60" data-act="t-qrfull" title="Perbesar QR" id="qr-box">${qrSvg(url)}</button>
